CREATE TABLE IF NOT EXISTS observations (id TEXT PRIMARY KEY, class_room TEXT NOT NULL, student_number TEXT NOT NULL, author_alias TEXT NOT NULL, group_name TEXT NOT NULL, location_category TEXT NOT NULL, location_detail TEXT NOT NULL DEFAULT '', waste_scene TEXT NOT NULL, waste_cause TEXT NOT NULL, sensor_idea TEXT NOT NULL DEFAULT '', photo_data_url TEXT NOT NULL DEFAULT '', photo_caption TEXT NOT NULL DEFAULT '', privacy_confirmed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')));
CREATE INDEX IF NOT EXISTS idx_observations_class_group ON observations (class_room, group_name, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_observations_created_at ON observations (created_at DESC);
CREATE TABLE IF NOT EXISTS group_auth_codes (class_room TEXT NOT NULL, group_name TEXT NOT NULL, auth_code TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), PRIMARY KEY (class_room, group_name));
CREATE TABLE IF NOT EXISTS group_topics (id TEXT PRIMARY KEY, class_room TEXT NOT NULL, group_name TEXT NOT NULL, group_members TEXT NOT NULL, selected_location TEXT NOT NULL, reference_photo_data_url TEXT NOT NULL DEFAULT '', project_title TEXT NOT NULL, core_question TEXT NOT NULL, selection_reason TEXT NOT NULL, control_condition_when TEXT NOT NULL DEFAULT '', control_condition_then TEXT NOT NULL DEFAULT '', control_condition_draft TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), UNIQUE (class_room, group_name));
CREATE INDEX IF NOT EXISTS idx_group_topics_created_at ON group_topics (created_at DESC);
CREATE TABLE IF NOT EXISTS birdseye_projects (class_room TEXT NOT NULL, group_name TEXT NOT NULL, prompt_fields TEXT NOT NULL DEFAULT '', prompt_text TEXT NOT NULL DEFAULT '', prompt_submitted_at TEXT NOT NULL DEFAULT '', final_version INTEGER, review_json TEXT NOT NULL DEFAULT '', review_saved_at TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), PRIMARY KEY (class_room, group_name));
CREATE TABLE IF NOT EXISTS birdseye_images (id TEXT PRIMARY KEY, class_room TEXT NOT NULL, group_name TEXT NOT NULL, version INTEGER NOT NULL, image_data_url TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), UNIQUE (class_room, group_name, version));
